-- Research protocols remain optional for existing topics and clients.
ALTER TABLE "glean_topic" ADD COLUMN "search_protocol" jsonb NULL;
ALTER TABLE "glean_paper_review" ADD COLUMN "evidence" jsonb NULL;

-- Long-term run/request/occurrence ledgers have application-enforced logical links.
-- Request rows are written before HTTP; unresolved pending rows remain uncertain.
CREATE TABLE "glean_search_run" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "state_key" character varying NOT NULL,
  "payload" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL,
  "created_by" bigint NULL, "updated_by" bigint NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX "gleansearchrun_state_key_id" ON "glean_search_run" ("state_key", "id");
CREATE TABLE "glean_search_request" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "run_id" bigint NOT NULL, "query_id" character varying NOT NULL,
  "source" character varying NOT NULL, "status" character varying NOT NULL,
  "payload" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL,
  "created_by" bigint NULL, "updated_by" bigint NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX "gleansearchrequest_run_id_id" ON "glean_search_request" ("run_id", "id");
CREATE TABLE "glean_search_occurrence" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "run_id" bigint NOT NULL, "request_id" bigint NOT NULL, "ordinal" bigint NOT NULL,
  "source" character varying NOT NULL, "source_id" character varying NOT NULL,
  "record_key" character varying NOT NULL, "payload" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL,
  "created_by" bigint NULL, "updated_by" bigint NULL,
  PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "gleansearchoccurrence_request_id_ordinal" ON "glean_search_occurrence" ("request_id", "ordinal");
CREATE INDEX "gleansearchoccurrence_run_id_id" ON "glean_search_occurrence" ("run_id", "id");
